const msg = $input.first().json;
const text = msg.message?.text || msg.message?.caption || '[IMAGEN ADJUNTA]';
const safeText = text.replace(/"/g, "'").replace(/\n/g, ' ').replace(/\\/g, '');

const prompt = `SISTEMA: Clasificador fiscal RESICO. Responde SOLO JSON puro. Cero texto extra. Cero markdown.

REGLAS DE PRIORIDAD (aplica en orden):
1. Si menciona montos, millones, MDP, limite, tasa, porcentaje, ISR, IVA, SAT, regimen, declaracion, e.firma, buzon tributario → CONSULTA_FISCAL
2. Si menciona timbrar, sellar, CFDI, factura, RFC, cancelar factura, complemento → SOLICITUD_FACTURA
3. Si menciona ticket, gasto, recibo, nota, compre, gaste, acreditamiento → REGISTRO_GASTO
4. Si menciona pague, deposite, transferencia, SPEI, OXXO, comprobante, referencia → REPORTE_PAGO
5. Si es saludo, despedida o pregunta no fiscal → OTROS

JERGA MEXICANA:
- la chiva / el chivo / hacienda = SAT
- timbrar / sellar = emitir CFDI
- lana / varo / baro / fierro = dinero
- chambear / jalar = trabajar
- 3 MDP / 3 millones / 3.5 = limite de ingresos RESICO

CONTEXTO RESICO CRITICO:
- Limite anual: 3,500,000 MXN. Superarlo = expulsion del regimen
- ISR: sobre ingresos BRUTOS, tasas 1% al 2.5%. SIN deducciones
- IVA: SI permite acreditamiento con factura
- e.firma vencida o Buzon inactivo = multas $3,420 a $10,260 MXN

Campo explanation: escribe la RESPUESTA DIRECTA al usuario, no una descripcion. Ejemplo: si pregunta por el limite, explanation = 'El limite RESICO es $3,500,000 MXN anuales. Si lo superas el SAT te mueve a Actividad Empresarial automaticamente.'

Formato OBLIGATORIO (unicamente esto, sin nada mas):
{"intent":"CATEGORIA","confidence":0.95,"explanation":"respuesta directa al usuario"}

Mensaje a clasificar: "${safeText}"`;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 300 }
};

return [{
  json: {
    payload,
    telegram_chat_id: msg.message?.chat?.id?.toString() || 'unknown',
    telegram_message_text: text
  }
}];

const geminiResponse = $input.first().json;
const telegramData = $('Construir Payload Gemini').first().json;

let rawText = '';
try {
  rawText = geminiResponse.candidates[0].content.parts[0].text || '';
} catch (e) {
  return [{ json: {
    intent: 'OTROS', confidence: 0.5,
    explanation: 'Hola, soy Aliado RESICO. ¿En qué te puedo ayudar con tu contabilidad RESICO hoy?',
    telegram_chat_id: telegramData.telegram_chat_id,
    telegram_message_text: telegramData.telegram_message_text
  }}];
}

let cleaned = rawText.replace(/```(?:json)?\s*([\s\S]*?)```/gi, '$1').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  return [{ json: {
    intent: 'OTROS', confidence: 0.5,
    explanation: 'No entendí tu consulta. ¿Puedes reformularla?',
    telegram_chat_id: telegramData.telegram_chat_id,
    telegram_message_text: telegramData.telegram_message_text
  }}];
}

let parsed;
try {
  parsed = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  return [{ json: {
    intent: 'OTROS', confidence: 0.5,
    explanation: 'Hubo un error procesando tu mensaje. Intenta de nuevo.',
    telegram_chat_id: telegramData.telegram_chat_id,
    telegram_message_text: telegramData.telegram_message_text
  }}];
}

const validIntents = ['CONSULTA_FISCAL','SOLICITUD_FACTURA','REGISTRO_GASTO','REPORTE_PAGO','OTROS'];
if (!validIntents.includes(parsed.intent)) parsed.intent = 'OTROS';
parsed.confidence = Math.max(0, Math.min(1, parsed.confidence || 0.5));
parsed.telegram_chat_id = telegramData.telegram_chat_id;
parsed.telegram_message_text = telegramData.telegram_message_text;

return [{ json: parsed }];

